comms.text:
@1 וְאַכְנֵשׁ משֶׁה יָת כָּל כְּנִשְׁתָּא דִבְנֵי יִשְרָאֵל וַאֲמַר לְהוֹן אִלֵין פִּתְגָמַיָא דִי פַקֵד יְיָ לְמֶעְבַּד יָתְהוֹן:
@2 שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִדְתָּא וּבְיוֹמָא שְׁבִיעָאָה יְהֵי לְכוֹן קוּדְשָׁא שַׁבָּא שַׁבְּתָא קֳדָם יְיָ כָּל דְיַעֲבֵד בֵּה עִבִדְתָּא יִתְקְטֵל:
@3 לָא תְבַעֲרוּן אֶשָׁתָא בְּכֹל מוֹתְבָנֵיכוֹן בְּיוֹמָא דְשַׁבְּתָא:
@4 וַאֲמַר משֶׁה לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמֵימָר דֵין פִּתְגָּמָא דִי פַקֵד יְיָ לְמֵימָר:
@5 סָבוּ מִנְכוֹן אַפְרָשׁוּתָא קֳדָם יְיָ כֹּל דְיִתְרְעֵי לִבֵּהּ יַיְתֵי יָת אַפְרָשׁוּתָא קֳדָם יְיָ דַהֲבָא וְכַסְפָא וּנְחָשָׁא:
@6 וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ וּמֵעַזֵי:
@7 וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי דְסַסְגוֹנָא וְאָעֵי שִׁטִין:
@8 וּמִשְׁחָא לְאַנְהָרוּתָא וּבוּסְמַיָא לִמְשַׁח רְבוּתָא וְלִקְטֹרֶת בּוּסְמַיָא:
@9 וְאַבְנֵי בוּרְלָא וְאַבְנֵי אַשְׁלָמוּתָא לְשַׁקָעָא בְּאֵפוֹדָא וּבְחוּשְׁנָא:
@10 וְכָל חַכִּימֵי לִבָּא בְּכוֹן יֵיתוּן וְיַעְבְדוּן יָת כָּל דִי פַקֵד יְיָ:
@11 יָת מַשְׁכְּנָא יָת פְּרָסֵהּ וְיָת חוֹפָאֵהּ יָת פּוּרְפוֹהִי וְיָת דַפּוֹהִי יָת עַבְרוֹהִי יָת עַמוּדוֹהִי וְיָת סַמְכוֹהִי:
@12 יָת אֲרוֹנָא וְיָת אֲרִיחוֹהִי יָת כַּפֻּרְתָּא וְיָת פָּרֻכְתָּא דִפְרָסָא:
@13 יָת פָּתוֹרָא וְיָת אֲרִיחוֹהִי וְיָת כָּל מָנוֹהִי וְיָת לְחֵם אַפַּיָא:
@14 וְיָת מְנַרְתָּא דְאַנְהוֹרֵי וְיָת מָנָהָא וְיָת בּוֹצִינָהָא וְיָת מִשְׁחָא דְאַנְהָרוּתָא:
@15 וְיָת מַדְבְּחָא דִקְטוֹרֶת בּוּסְמַיָא וְיָת אֲרִיחוֹהִי וְיָת מִשְׁחָא דִרְבוּתָא וְיָת קְטֹרֶת בּוּסְמַיָא וְיָת פְּרָסָא דְתַרְעָא לִתְרַע מַשְׁכְּנָא:
@16 יָת מַדְבְּחָא דַעֲלָתָא וְיָת סְרָדָא דִנְחָשָׁא דִילֵהּ יָת אָרִיחוֹהִי וְיָת כָּל מָנוֹהִי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ:
@17 יָת סְרָדֵי דַרְתָּא יָת עַמוּדוֹהִי וְיָת סַמְכָהָא וְיָת פְּרָסָא דִתְרַע דַרְתָּא:
@18 יָת סִכֵּי מַשְׁכְּנָא וְיָת סִכֵּי דְדַרְתָּא וְיָת אַטוּנֵיהוֹן:
@19 יָת לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְקוּדְשָׁא יָת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן כַּהֲנָא וְיָת לְבוּשֵׁי בְנוֹהִי לְשַׁמָשָׁא:
@20 וּנְפָקוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִן קֳדָם משֶׁה:
@21 וַאֲתוֹ כָּל גְבַר דְאִתְרְעֵי לִבֵּהּ וְכֹל דִי אַשְׁלֵמַת רוּחֵהּ יָתֵהּ אַיְתִיאוּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ לַעֲבִידַת מַשְׁכַּן זִמְנָא וּלְכָל פֻּלְחָנֵהּ וְלִלְבוּשֵׁי קוּדְשָׁא:
@22 וּמַיְתַן גֻבְרַיָא עַל נְשַׁיָא כֹּל דְאִתְרְעֵי לִבֵּהּ אַיְתִיאוּ שֵׁירִין וְשִׁבְכִין וְעִזְקַן וּמָחוּךְ כָּל מָן דִדְהַב וְכָל גְּבַר דִי אֲרֵים אֲרָמוּת דַהֲבָא קֳדָם יְיָ:
@23 וְכָל גְבַר דְאִשְׁתְּכַח עִמֵהּ תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ וּמֵעַזֵי וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי סַסְגוֹנָא אַיְתִיאוּ:
@24 כָּל דַאֲרֵים אֲרָמוּת כְּסַף וּנְחַשׁ אַיְתִיאוּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ וְכֹל דִי אִשְׁתְּכַח עִמֵהּ אָעֵי שִׁטִין לְכָל עִבִידַת פֻּלְחָנָא אַיְתִיאוּ:
@25 וְכָל אִתְּתָא חַכִּימַת לִבָּא בִּידָהָא מְעַזְלָא וּמַיְתַן כַּד עָזֵל יָת תִּכְלָא וְיָת אַרְגְוָנָא יָת צְבַע זְהוֹרִי וְיָת בּוּצָא:
@26 וְכָל נְשַׁיָא דְאִתְרְעֵי לִבְּהֶן עִמְהֶן בְּחָכְמָא עַזְלַן יָת מֵעַזְיָא:
@27 וְרַבְרְבַיָא אַיְתִיאוּ יָת אַבְנֵי בוּרְלָא וְיָת אַבְנֵי אַשְׁלָמוּתָא לְשַׁקָעָא בְאֵפוֹדָא וּבְחוּשְׁנָא:
@28 וְיָת בּוּסְמָא וְיָת מִשְׁחָא לְאַנְהָרוּתָא וּלְמִשְׁחָא דִרְבוּתָא וְלִקְטוֹרֶת בּוּסְמַיָא:
@29 כָּל גְבַר וְאִתְּתָא דְאִתְרְעֵי לִבְּהוֹן עִמְהוֹן לְאַיְתָאָה לְכָל עִבִדְתָּא דִי פַקֵד יְיָ לְמֶעְבַּד בִּידָא דְמשֶׁה אַיְתִיאוּ בְנֵי יִשְׂרָאֵל נְדַבְתָּא קֳדָם יְיָ:
@30 וַאֲמַר משֶׁה לִבְנֵי יִשְׂרָאֵל חֲזוֹ דְרַבִּי יְיָ בְּשׁוּם בְּצַלְאֵל בַּר אוּרִי בַר חוּר לְשִׁבְטָא דִיהוּדָה:
@31 וְאַשְׁלֵם עִמֵהּ רוּחַ נְבוּאָה מִן קֳדָם יְיָ בְּחָכְמְתָא בְּסוּכְלְתָנוּ וּבְמַדַע וּבְכָל עִבִידָא:
@32 וּלְאַלָפָא אוּמַנְוָן לְמֶעְבַּד בְּדַהֲבָא וּבְכַסְפָא וּבִנְחָשָׁא:
@33 וּבְאוּמָנוּת אֶבֶן טָבָא לְאַשְׁלָמָא וּבְנַגָרוּת אָעָא לְמֶעְבַּד בְּכָל עִבִידַת אוּמַנְוָן:
@34 וּלְאַלָפָא יְהַב בְּלִבֵּהּ הוּא וְאָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן:
@35 אַשְׁלֵם עִמְהוֹן חַכִּימוּת לִבָּא לְמֶעְבַּד כָּל עִבִידַת נַגָר וְאָמָן וְצַיָר בְּתִכְלָא וּבְאַרְגְוָנָא בִּצְבַע זְהוֹרִי וּבְבוּצָא וּמַחֵי עָבְדֵי כָּל עֲבִידָא וּמַלְפֵי אוּמַנְוָן:
@36 וַעֲבַד בְּצַלְאֵל וְאָהֳלִיאָב וְכָל גְבַר חַכִּים לִבָּא דִיהַב יְיָ חָכְמָא וְסוּכְלְתָנוּתָא בְּהוֹן לְמִדַע לְמֶעְבַּד יָת כָּל עִבִידַת פָלְחַן קוּדְשָׁא לְכֹל דִי פַקֵד יְיָ:
@37 וּקְרָא משֶׁה לִבְצַלְאֵל וּלְאָהֳלִיאָב וּלְכָל גְּבַר חַכִּים לִבָּא דִיהַב יְיָ חָכְמְתָא בְּלִבֵּה כָּל דְאִתְרְעֵי לִבֵּהּ לְמִקְרַב לְעִבִדְתָּא לְמֶעְבַּד יָתַהּ:
@38 וּנְסִיבוּ מִן קֳדָם משֶׁה יָת כָּל אַפְרָשׁוּתָא דִי אַיְתִיאוּ בְּנֵי יִשְׂרָאֵל לְעִבִידַת פָּלְחַן קוּדְשָׁא לְמֶעְבַּד יָתַהּ וְאִנוּן מַיְתַן לֵהּ עוֹד נְדַבְתָּא בִּצְפַר בִּצְפָר:
@39 וַאֲתוֹ כָּל חַכִּימַיָא דְעָבְדִין יָת כָּל עִבִידַת קוּדְשָׁא גְבַר גְבַר מֵעִבִדְתֵּהּ דְאִנוּן עָבְדִין:
@40 וַאֲמָרוּ לְמשֶׁה לְמֵימַר מַסְגַן עַמָא לְאַיְתָאָה מִסַת פָּלְחָנָא לְעִבִדְתָּא דְפַקֵד יְיָ לְמֶעְבַּד יָתַהּ:
@41 וּפַקֵד משֶׁה וַאַעֲבַרוּ כְרוֹזָא בְּמַשְׁרִיתָא לְמֵימַר גְבַר וְאִתְּתָא לָא יַעַבְדוּן עוֹד עִבִדְתָּא לְאַפְרָשׁוּת קוּדְשָׁא וּפְסַק עַמָא מִלְאַיְתָאָה:
@42 וְעִבִדְתָּא הֲוַת מִסַת לְכָל עִבִדְתָּא לְמֶעְבַּד יָתַהּ וִיתָרָת:
@43 וַעֲבָדוּ כָל חַכִּימֵי לִבָּא בְּעָבְדֵי עִבִדְתָּא יָת מַשְׁכְּנָא עֲשַׂר יְרִיעָן דְבוּץ שְׁזִיר וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי צוּרַת כְּרוּבִין עוֹבַד אֳמָן עֲבַד יָתְהוֹן:
@44 אֻרְכָּא דִירִעֲתָא חֲדָא עַסְרִין וּתְמַנְיָא אַמִין וּפוּתְיָא אַרְבַּע אַמִין דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְכָל יְרִיעָתָא:
@45 וְלָפֵף יָת חָמֵשׁ יְרִיעָן חֲדָא עִם חֲדָא וְחָמֵשׁ יְרִיעָן לָפֵף חֲדָא עִם חֲדָא:
@46 וַעֲבַד עֲנוּבִין דְתִכְלָא עַל סִפְתָא דִירִעֲתָא חֲדָא מִסִטְרָא בֵּית לוֹפֵי כֵּן עֲבַד בְּסִפְתָא דִירִיעֲתָא בְּסִטְרָא בֵּית לוֹפֵי תִּנְיֵתָא:
@47 חַמְשִׁין עֲנוּבִין עֲבַד בִּירִיעֲתָא חֲדָא וְחַמְשִׁין עֲנוּבִין עֲבַד בְּסִטְרָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיֵתָא מְכַוְנָן עֲנוּבַיָא חֲדָא לָקֳבֵל חֲדָא:
@48 וַעֲבַד חַמְשִׁין פּוּרְפִין דִדְהַב וְלָפֵף יָת יְרִיעֲתָא חֲדָא עִם חֲדָא בְּפוּרְפַיָא וַהֲוָה מַשְׁכְּנָא חָד:
@49 וַעֲבַד יְרִיעָן דִמְעַזֵי לִפְרָסָא עַל מַשְׁכְּנָא חַד עֲשַׂר יְרִיעָן עֲבַד יָתְהֶן:
@50 אֻרְכָּא דִירִיעֲתָא חֲדָא תְּלָתִין בְּאַמִין וְאַרְבַּע אַמִין פּוּתְיָא דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְחַד עֲשַׂר יְרִיעָן:
@51 וְלָפֵף יָת חָמֵשׁ יְרִיעָן לְחוֹד וְיָת שִׁית יְרִיעָן לְחוֹד:
@52 וַעֲבַד עֲנוּבִין חַמְשִׁין עַל סִפְתָא דִירִיעֲתָא בְּסִטְרָא בֵּית לוֹפֵי וְחַמְשִׁין עֲנוּבִין עֲבַד עַל סִפְתָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיֵתָא:
@53 וַעֲבַד פּוּרְפִין דִנְחָשָׁא חַמְשִׁין לְלַפָּפָא יָת מַשְׁכְּנָא לְמֶהֱוֵי חָד:
@54 וַעֲבַד חוֹפָאָה לְמַשְׁכְּנָא מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְחוֹפָאָה מַשְׁכֵי דְסַסְגוֹנָא מִלְעֵלָא:
@55 וַעֲבַד יָת דַפַּיָא לְמַשְׁכְּנָא דְאָעֵי שִׁטִין קָיְמִין:
@56 עֲשַׂר אַמִין אֻרְכָּא דְדַפָּא וְאַמְתָא וּפַלְגוּת אַמְתָא פּוּתְיָא דְדַפָּא חָד:
@57 תַּרְתֵּין צִירִין לְדַפָּא חַד מְשַׁלְבִין חֲדָא לָקֳבֵל חֲדָא כֵּן עֲבַד לְכֹל דַפֵּי מַשְׁכְּנָא:
@58 וַעֲבַד יָת דַפַּיָא לְמַשְׁכְּנָא עֶסְרִין דַפִּין לְרוּחַ עֵבַר דָרוֹמָא:
@59 וְאַרְבְּעִין סַמְכִין דִכְסַף עֲבַד תְּחוֹת עֶסְרִין דַפִּין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי:
@60 וְלִסְטַר מַשְׁכְּנָא תִּנְיֵתָא לְרוּחַ צִפּוּנָא עֲבַד עֶסְרִין דַפִּין:
@61 וְאַרְבְּעִין סַמְכֵיהוֹן דִכְסָף תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@62 וְלִסְיָפֵי מַשְׁכְּנָא מַעַרְבָא עֲבַד שִׁתָּא דַפִין:
@63 וּתְרֵין דַפִין עֲבַד לְזָוְיַת מַשְׁכְּנָא בְּסוֹפֵיהוֹן:
@64 וַהֲווֹ מְכַוְנִין מִלְרַע וְכַחֲדָא הֲווֹ מְכַוְנִין עַל רֵישֵׁהּ לְעִזְקָתָא חֲדָא כֵּן עֲבַד לְתַרְוֵיהוֹן לִתְרֵין זָוְיָן:
@65 וַהֲווֹ תְּמַנְיָא דַפִּין וְסַמְכֵיהוֹן דִכְסַף שִׁתָּא עֲשַׂר סַמְכִין תְּרֵין סַמְכִין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@66 וַעֲבַד עַבְּרֵי דְאָעֵי שִׁטִין חַמְשָׁא לְדַפֵּי סְטַר מַשְׁכְּנָא חָד:
@67 וְחַמְשָׁא עַבְּרִין לְדַפֵּי סְטַר מַשְׁכְּנָא תִּנְיֵתָא וְחַמְשָׁא עַבְּרִין לְדַפֵּי מַשְׁכְּנָא לְסוֹפֵיהוֹן מַעַרְבָא:
@68 וַעֲבַד יָת עַבְּרָא מְצִיעָאָה לְאַעְבָּרָא בְּגוֹ דַפַּיָא מִן סְיָפֵי לִסְיָפֵי:
@69 וְיָת דַפַּיָא חֲפָא דַהֲבָא וְיָת עִזְקָתְהוֹן עֲבַד דַהֲבָא אַתְרָא לְעַבְּרַיָא וַחֲפָא יָת עַבְּרַיָא דַהֲבָא:
@70 וַעֲבַד יָת פָּרֻכְתָּא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן עֲבַד יָתַהּ צוּרַת כְּרוּבִין:
@71 וַעֲבַד לַהּ אַרְבְּעָא עַמוּדֵי שִׁטִין וַחֲפָנוּן דַהֲבָא וָוֵיהוֹן דַהֲבָא וְאַתִּיךְ לְהוֹן אַרְבְּעָא סַמְכִין דִכְסָף:
@72 וַעֲבַד פְּרָסָא לִתְרַע מַשְׁכְּנָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד צַיָר:
@73 וְיָת עַמוּדוֹהִי חַמְשָׁא וְיָת וָוֵיהוֹן וַחֲפָא רֵישֵׁיהוֹן וְכִבּוּשֵׁיהוֹן דַהֲבָא וְסַמְכֵיהוֹן חַמְשָׁא נְחָשָׁא:
@74 וַעֲבַד בְּצַלְאֵל יָת אֲרוֹנָא דְאָעֵי שִׁטִין תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכֵּהּ וְאַמְתָא וּפַלְגָא פְתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵהּ:
@75 וַחֲפָהִי דְהַב דְכֵי מִגָּו וּמִבָּרָא וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@76 וְאַתִּיךְ לֵהּ אַרְבַּע עִזְקַן דִדְהַב עַל אַרְבַּע זִוְיָתֵהּ וְתַרְתֵּין עִזְקַן עַל סִטְרֵהּ חַד וְתַרְתֵּין עִזְקַן עַל סִטְרֵהּ תִּנְיֵתָא:
@77 וַעֲבַד אֲרִיחֵי דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן דַהֲבָא:
@78 וְאָעֵיל יָת אֲרִיחַיָא בְּעִזְקָתָא עַל סִטְרֵי אֲרוֹנָא לְמִטָל יָת אֲרוֹנָא:
@79 וַעֲבַד כַּפֻּרְתָּא דְהַב דְכֵי תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכַּהּ וְאַמְתָא וּפַלְגָא פְתָיַהּ:
@80 וַעֲבַד תְּרֵין כְּרוּבִין דִדְהָב נְגִיד עֲבַד יָתְהוֹן מִתְּרֵין סִטְרֵי כַפֻּרְתָּא:
@81 כְּרוּבָא חַד מִסִטְרָא מִכָּא וּכְרוּבָא חַד מִסִטְרָא מִכָּא מִן כַּפֻּרְתָּא עֲבַד יָת כְּרוּבַיָא מִתְּרֵין סִטְרוֹהִי:
@82 וַהֲווֹ כְרוּבַיָא פְּרִיסָן גַדְפֵיהוֹן לְעֵלָא נָטְלִין בְּגַדְפֵיהוֹן עַל כַּפֻּרְתָּא וְאַפֵּיהוֹן חַד לָקֳבֵל חַד לָקֳבֵל כַּפֻּרְתָּא הֲווֹ אַפֵּי כְרוּבַיָא:
@83 וַעֲבַד יָת פָּתוֹרָא דְאָעֵי שִׁטִין תַּרְתֵּין אַמִין אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵהּ:
@84 וַחֲפָא יָתֵהּ דְהַב דְכֵי וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@85 וַעֲבַד לֵהּ גְדַנְפָא רוּמֵהּ פּוּשְׁכָא סְחוֹר סְחוֹר וַעֲבַד דֵיר דִדְהַב לִגְדַנְפֵהּ סְחוֹר סְחוֹר:
@86 וְאַתִּיךְ לֵהּ אַרְבַּע עִזְקַן דִדְהָב וִיהַב יָת עִזְקֳתָא עַל אַרְבַּע זִוְיָתָא דִי לְאַרְבַּע רַגְלוֹהִי:
@87 לָקֳבֵל גְדַנְפָא הֲווֹ עִזְקָתָא אַתְרָא לַאֲרִיחַיָא לְמִטַל יָת פָּתוֹרָא:
@88 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִּין וַחֲפָא יָתְהוֹן דַהֲבָא לְמִטַל יָת פָּתוֹרָא:
@89 וַעֲבַד יָת מָנַיָא דִי עַל פָּתוֹרָא יָת מָגִיסוֹהִי וְיָת בָּזִיכּוֹהִי וְיָת מְכִילָתֵהּ וְיָת קַשְׂוָתָא דִי יִתְנַסַךְ בְּהוֹן דְהַב דְכֵי:
@90 וַעֲבַד יָת מְנַרְתָּא דְהַב דְכֵי נְגִיד עֲבַד יָת מְנַרְתָּא שִׁידַהּ וּקְנַהּ כַּלִידָהָא חֵזוּרָהָא וְשׁוֹשַׁנָהָא מִנַהּ הֲווֹ:
@91 וְשִׁתָּא קְנִין נָפְקִין מִסִטְרָהָא תְּלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ חַד וּתְלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ תִּנְיָנָא:
@92 תְּלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשָׁן וּתְלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשָׁן כֵּן לְשִׁתָּא קְנִין דְנָפְקִין מִן מְנַרְתָּא:
@93 וּבִמְנַרְתָּא אַרְבְּעָא כַלִידִין מְצַיְרִין חֵזוּרָהָא וְשׁוֹשַׁנָהָא:
@94 וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ לְשִׁתָּא קְנִין דְנַפְקִין מִנַהּ:
@95 חֵזוּרֵיהוֹן וּקְנֵיהוֹן מִנַהּ הֲווֹ כֻּלַהּ נְגִידָא חֲדָא דְהַב דְכֵי:
@96 וַעֲבַד יָת בּוֹצִינָהָא שִׁבְעָא וְצִבְיְתָהָא וּמַחְתְּיָתָהָא דְהַב דְכֵי:
@97 כִּכְּרָא דְהַב דְכֵי עֲבַד יָתַהּ וְיָת כָּל מָנָהָא:
@98 וַעֲבַד יָת מַדְבְּחָא דִקְטֹּרֶת בּוּסְמַיָא דְאָעֵי שִׁטִין אַמְתָא אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ מְרַבַּע וְתַרְתֵּין אַמִין רוּמֵהּ מִנֵהּ הֲווֹ קַרְנוֹהִי:
@99 וַחֲפָא יָתֵהּ דְהַב דְכֵי יָת אִגָרֵה וְיָת כָּתְלוֹהִי סְחוֹר סְחוֹר וְיָת קַרְנוֹהִי וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@100 וְתַרְתֵּין עִזְקַן דִדְהַב עֲבַד לֵהּ מִלְרַע לְדֵירֵהּ עַל תַּרְתֵּין זִוְיָתֵהּ עַל תְּרֵין סִטְרוֹהִי לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָתֵהּ בְּהוֹן:
@101 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן דַהֲבָא:
@102 וַעֲבַד יָת מִשְׁחָא דִרְבוּתָא קוּדְשָׁא וְיָת קְטֹרֶת בּוּסְמַיָא דְכֵי עוֹבַד בּוּסְמָנוּ:
@103 וַעֲבַד יָת מַדְבְּחָא דַעֲלָתָא דְאָעֵי שִׁטִין חֲמֵשׁ אַמִין אֻרְכֵּהּ וַחֲמֵשׁ אַמִין פְּתָיֵהּ מְרַבַּע וּתְלָתָא אַמִין רוּמֵהּ:
@104 וַעֲבַד קַרְנוֹהִי עַל אַרְבַּע זִוְיָתֵהּ מִנֵהּ הֲווֹ קַרְנוֹהִי וַחֲפָא יָתֵהּ נְחָשָׁא:
@105 וַעֲבַד יָת כָּל מָנֵי מַדְבְּחָא יָת פְּסַכְתְּרָוָתָא וְיָת מַגְרוֹפְיָתָא וְיָת מִזְרְקָתָא יָת צִנוֹרְיָתָא וְיָת מַחְתְּיָתָא כָּל מָנוֹהִי עֲבַד נְחָשָׁא:
@106 וַעֲבַד לְּמַדְבְּחָא סְרָדָא עוֹבַד מְצַדְתָּא דִנְחָשָׁא תְּחוֹת סוֹבָבֵהּ מִלְרַע עַד פַּלְגֵהּ:
@107 וְאַתִּיךְ אַרְבַּע עִזְקָתָא בְּאַרְבַּע סִטְרָתָא לִסְרָדָא דִנְחָשָׁא אַתְרָא לַאֲרִיחַיָא:
@108 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן נְחָשָׁא:
@109 וְאָעֵיל יָת אֲרִיחַיָא בְּעִזְקָתָא עַל סִטְרֵי מַדְבְּחָא לְמִטַל יָתֵהּ בְּהוֹן חֲלִיל לוּחִין עֲבַד יָתֵהּ:
@110 וַעֲבַד יָת כִּיוֹרָא נְחָשָׁא וְיָת בְּסִיסֵהּ נְחָשָׁא בְּמֶחְזְיַן נְשַׁיָא דְאָתְיָן לְצַלָאָה בִּתְרַע מַשְׁכַּן זִמְנָא:
@111 וַעֲבַד יָת דַרְתָּא לְרוּחַ עֵבַר דָרוֹמָא סְרָדֵי דַרְתָּא דְבוּץ שְׁזִיר מְאָה בְאַמִין:
@112 עַמוּדֵיהוֹן עֶסְרִין וְסַמְכֵיהוֹן עֶסְרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@113 וּלְרוּחַ צִפּוּנָא מְאָה אַמִין עַמוּדֵיהוֹן עֶסְרִין וְסַמְכֵיהוֹן עֶסְרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@114 וּלְרוּחַ מַעַרְבָא סְרָדִין חַמְשִׁין בְּאַמִין עֲמוּדֵיהוֹן עַסְרָא וְסַמְכֵיהוֹן עַסְרָא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@115 וּלְרוּחַ קִדוּמָא מָדִינְחָא חַמְשִׁין אַמִין:
@116 סְרָדִין חֲמֵשׁ עֶסְרֵי אַמִין לְעִבְרָא עַמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@117 וּלְעִבְרָא תִנְיֵתָא מִכָּא וּמִכָּא לִתְרַע דַרְתָּא סְרָדִין חֲמֵשׁ עֶסְרֵי אַמִין עַמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@118 כָּל סְרָדֵי דְדַרְתָּא סְחוֹר סְחוֹר דְבוּץ שְׁזִיר:
@119 וְסַמְכַיָא לְעַמוּדַיָא נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסַף וְחִפּוּי רֵישֵׁיהוֹן דִכְסָף וְאִנוּן מְכַבְּשִׁין דִכְסָף כָּל עַמוּדֵי דַרְתָּא:
@120 וּפְרָסָא דִתְרַע דַרְתָּא עוֹבַד צַיָר תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר וְעֶסְרִין אַמִין אֻרְכָּא וְרוּמָא בְּפוּתְיָא חֲמֵשׁ אַמִין לָקֳבֵל סְרָדֵי דַרְתָּא:
@121 וְעַמוּדֵיהוֹן אַרְבְּעָא וְסַמְכֵיהוֹן אַרְבְּעָא נְחָשָׁא וָוֵיהוֹן דִכְסַף וְחִפּוּי רֵישֵׁיהוֹן וְכִבּוּשֵׁיהוֹן דִכְסָף:
@122 וְכָל סִכַּיָא לְמַשְׁכְּנָא וּלְדַרְתָּא סְחוֹר סְחוֹר דִנְחָשָׁא: ססס:

@1 **ויקהל משה.** למחרת יום הכפורים כשירד מן ההר, והוא לשון הפעיל, שאינו אוסף אנשים בידים, אלא הן נאספים על פי דבורו, ותרגומו ואכנש:
@2 **ששת ימים.** הקדים להם אזהרת שבת לצווי מלאכת המשכן, לומר שאינה דוחה את השבת:
@3 **לא תבערו אש.** יש מרבותינו אומרים הבערה ללאו יצאת, ויש אומרים לחלק יצאת:
@4 **זה הדבר אשר צוה ה'.** לי לאמר לכם:
@5 **נדיב לבו.** על שם שלבו נדבו קרוי נדיב לב. כבר פרשתי נדבת המשכן ומלאכתו במקום צואתן:
@11 **את המשכן.** יריעות התחתונות הנראות בתוכו קרויים משכן: **את אהלו.** הוא אהל יריעות עזים העשוי לגג: **ואת מכסהו.** מכסה עורות האילים והתחשים:
@12 **ואת פרכת המסך.** פרוכת המחצה. כל דבר המגין, בין מלמעלה בין מכנגד, קרוי מסך וסכך, וכן (איוב א י) שכת בעדו, (הושע ב ח) הנני שך את דרכך:
@13 **לחם הפנים.** כבר פרשתי (שמות כה כח) על שם שהיו לו פנים לכאן ולכאן, שהוא עשוי כמין תבה פרוצה:
@14 **ואת כליה.** מלקחים ומחתות: **נרתיה.** לוציי''ש בלעז בזכים שהשמן והפתילות נתונין בהן: **ואת שמן המאור.** אף הוא צריך חכמי לב, שהוא משנה משאר שמנים, כמו שמפורש במנחות (דף פו א) מגרגרו בראש הזית, והוא כתית וזך:
@15 **מסך הפתח.** וילון שלפני המזרח שלא היו שם לא קרשים ולא יריעות:
@17 **את עמודיו ואת אדניה.** הרי חצר קרוי כאן לשון זכר ולשון נקבה, וכן דברים הרבה: **ואת מסך שער החצר.** וילון פרוש לצד המזרח עשרים אמה אמצעיות של רוחב החצר, שהיה חמשים רחב, וסתומין המנו לצד צפון חמש עשרה אמה וכן לדרום, שנאמר (שמות כז יד) וחמש עשרה אמה קלעים לכתף:
@18 **יתדת.** לתקוע ולקשור בהם סופי היריעות בארץ שלא ינועו ברוח: **מיתריהם.** חבלים לקשור:
@19 **בגדי השרד.** לכסות הארון והשלחן, והמנורה והמזבחות בשעת סלוק מסעות:
@22 **על הנשים.** עם הנשים וסמוכין אליהם: **חח.** הוא תכשיט של זהב עגול נתון על הזרוע, והוא הצמיד: **וכומז.** כלי זהב הוא נתון כנגד אותו מקום לאשה. ורבותינו פרשו שם כומז כאן מקום זמה:
@23 **וכל איש אשר נמצא אתו.** תכלת או ארגמן או תולעת שני או עורות אילים או תחשים כלם הביאו:
@26 **טוו את העזים.** היא היתה אמנות יתרה, שמעל גבי העזים טווין אותן:
@27 **והנשאם הביאו.** אמר ר' נתן מה ראו נשיאים להתנדב בחנכת המזבח בתחלה, ובמלאכת המשכן לא התנדבו בתחלה, אלא כך אמרו נשיאים יתנדבו צבור מה שמתנדבין, ומה שמחסירים אנו משלימין אותו. כיון שהשלימו צבור את הכל, שנאמר (שמות לו ז) והמלאכה היתה דים, אמרו נשיאים מה עלינו לעשות, הביאו את אבני השהם וגו' , לכך התנדבו בחנכת המזבח תחלה. ולפי שנתעצלו מתחלה נחסרה אות משמם והנשאם כתיב:
@30 **חור.** בנה של מרים היה:
@34 **ואהליאב.** משבט דן, מן הירודין שבשבטים מבני השפחות, והשוהו המקום לבצלאל למלאכת המשכן, והוא מגדולי השבטים, לקים מה שנאמר (איוב לד יט) ולא נכר שוע לפני דל:
@40 **מדי העבדה.** יותר מכדי צורך העבודה:
@41 **ויכלא.** לשון מניעה:
@42 **והמלאכה היתה דים לכל המלאכה.** ומלאכת ההבאה היתה דים של עושי המשכן. **לכל המלאכה.** של משכן **לעשות אותה.** ולהותיר: **והותר.** כמו (שמות ח יא) והכבד את לבו, (מלכים ב' ג כד) והכות את מואב:
@74 **ויעש בצלאל.** לפי שנתן נפשו על המלאכה יותר משאר חכמים, נקראת על שמו:
@109 **נבוב לחת.** נבוב הוא חלול, וכן (ירמיה נב, כא) ועביו ארבע אצבעות נבוב: **נבוב לחת.** הלוחות של עצי שטים לכל רוח והחלל באמצע:
@110 **במראת הצובאת.** בנות ישראל היו בידן מראות, שרואות בהן כשהן מתקשטות, ואף אותן לא עכבו מלהביא לנדבת המשכן, והיה מואס משה בהן, מפני שעשויים ליצר הרע, אמר לו הקדוש ברוך הוא קבל, כי אלו חביבין עלי מן הכל, שעל ידיהם העמידו הנשים צבאות רבות במצרים. כשהיו בעליהם יגעים בעבודת פרך, היו הולכות ומוליכות להם מאכל ומשתה ומאכילות אותם ונוטלות המראות, וכל אחת רואה עצמה עם בעלה במראה ומשדלתו בדברים, לומר אני נאה ממך, ומתוך כך מביאות לבעליהן לידי תאוה ונזקקות להם, ומתעברות ויולדות שם, שנאמר (שיר השירים ח ה) תחת התפוח עוררתיך, וזהו שנאמר במראות הצובאות. ונעשה הכיור מהם, שהוא לשום שלום בין איש לאשתו, להשקות ממים שבתוכו את שקנא לה בעלה ונסתרה, ותדע לך, שהן מראות ממש, שהרי נאמר (שמות לח כט ל) , ונחשת התנופה שבעים ככר וגו' , ויעש בה וגו' , וכיור וכנו לא הזכרו שם, למדת שלא היה נחשת של כיור מנחשת התנופה, כך דרש רבי תנחומא, וכן תרגם אנקלוס במחזית נשיא, והוא תרגום של מראות מירידויר''ש בלעז . וכן מצינו בישעיה (ישעיה ג כג) והגליונים, מתרגמנן ומחזיתא: **אשר צבאו.** להביא נדבתן:
@120 **לעמת קלעי החצר.** כמדת קלעי החצר:
@123 **ויעש חירום וגו'.** ואמר רבי, הכירות הן הן סירות, כמה דאת אמר ( זכריה יב ו ): ככיור אש בעצים; וכן ( שמואל א ב יד ): והכה בכיור: **הכיורות.** של נחשת, לדשן את המזבח: **היעים.** מגרפות של נחושת, שקורין ווידו"ל באשכנז, לחתות בהן דשן בתוך הסירות:
@125 **שני טורים רמונים.** מאה רמונים בטור, חרוזים בשרשרות:
@129 **יצקם.** התיכם והציקם כתבניתם: **במעבה האדמה.** ( תרגום: ) בעובי גרגשתא:
@130 **וינח שלמה.** מלשקול את משקל הכלים האלה מרוב מאד וחדל לספור משקלם:
@132 **חמש מימין וחמש משמאול.** אי אפשר לומר חמש מימין הפתח וחמש משמאל הפתח, אם כן מצינו מנורה בצפון, והתורה אמרה ( במדבר ג כט ): **על ירך המשכן תימנה.** אלא של משה באמצע, חמש מימינה, וחמש משמאלה: **והפרח.** של מנורה: **והנרות.** בזיכין שנותנין בהן השמן והפתילה: **והמלקחים.** שמרימים בהן את הפתילה מתוך השמן:
@133 **והספות.** כלי של מיני זמר הוא, וכן מזמרות: **והמזרקות.** לקבל דם: **והכפות.** לבזיכי לבונה: **והמחתות.** לחתות בהן תרומת הדשן וגחלים להוליך ממזבח החיצון למזבח הפנימי להקטיר קטורת: **והפותות.** מפתחות, שמעתי. שמפתחין בהם את המנעול: **לדלתות הבית.** שהוא קדש קדשים: **לדלתי הבית.** שהוא להיכל, כל פתחותיהן היו זהב:
@135 **חרש.** אומן: **וימלא את החכמה ואת התבונה ואת הדעת.** שלשה כלי אומנות שהעולם נברא בהן, שנאמר ( משלי ג יט-כ ): **בחכמה יסד ארץ, כונן שמים בתבונה, בדעתו תהומות נבקעו.** בשלשתן נבנה הבית:
@136 **את שני העמודים.** שהעמיד באולם יכין ובועז: **שמנה עשרה אמה קומת וגו'.** ובדברי הימים ( ב ג טו ) הוא אומר: שלשים וחמש אמה קומתן, שיצק שניהם כאחד, והאמה החסירה, אומר אני, חצי אמה היתה לכל אחד בראשו, שאינה דומה למלאכת שאר העמוד, כמו שאמור למטה ( פסוק כב ) בענין: ועל ראש העמודים מעשה שושן: **וחוט שתים עשרה אמה יסוב את העמוד השני.** לימד שהיה ארבע אמות על ארבע אמות עגול, שכל שיש בהקיפו שלשה טפחים, יש בו רוחב טפח, ועוביו ארבע אצבעות, והוא חלול, כך מפורש בסוף ספר ירמיהו ( נב כא ). והרי זה מקרא קצר, פירש ארכו של אחד, וילמד השני ממנו, ופירש הקיפו של שני, וילמד ממנו הראשון. וכן תרגם יונתן: וחוט משח תרתין עסרי אמין מקיף ליה, וכן לעמודא תניינא:
@137 **ושתי כותרות.** פומייל"ש בלע"ז: **מוצק.** טרישגיטי"ר בלע"ז: **חמש אמות קומת הכותרת האחת.** ובסוף הספר ( מלכים ב כה יז ) הוא אומר: שלש אמות, שנינו במשנה ארבעים ותשע מדות: שתי אמות התחתונות של כותרות היו שוות לעמוד, שלא היו בהן צורה, ושלש העליונות היו עודפות לחוץ, המוקפות צורה, שנאמר ( בפסוק יז ): **שבכים מעשה שבכה, כמין לולבין של דקל היו מוקפות.** ואומר אני, שלא מנה אותן שתי אמות התחתונות בסוף הספר, לפי שהיו שוות לעמוד, והעמוד תחוב בכותרת שתי אמות:
@138 **שבכים מעשה שבכה.** השבכות שהיה להם, דומה כמין כיפה, שקורין קויפ"א: **מעשה שבכה.** מוקפות היו צורות של לולבי דקל, כמו ( איוב יח ח ): ועל שבכה יתהלך, וגדילים היו להם כמעשה שרשראות: **שבעה לכותרת האחת.** שבעה לולבין היה להיקף אחד לשבכה אחת:
@139 **ושני טורים.** של רמונים ושל נחשת, הרמונים תחובים בשרשרות המקיפות את הכותרת, כך מפורש בדברי הימים ( ב ג טז ), ובמשנת ארבעים ותשע מדות: **לכסות את הכותרת אשר על ראש הרמונים.** הרי זה מקרא מסורס, לכסות הרמונים את הכותרות אשר על הראש, וכן היו הכותרות עשויות לפי סדר משמעות המקראות: כמין שני אגנים היתה כל אחת, אגן התחתון בית קיבולה למעלה, והוא קרוי 'גולה', כמו שאמור בענין ( לקמן פסוק מא ): וגולת הכותרות, ותרגמו יונתן: **אגני קרונתון.** העליון כפוי על התחתון, בית קיבולו למטה, והיא קרויה 'שבכה' כמה שנאמר בענין זה ( שם ): **והשבכות שתים לכסות את שתי גולת הכותרות.** נמצא רחבה במקום הדבק, ומשופעת ועולה, ומשופעת ויורדת, והוא קרוי בטן. וכן תרגם יונתן מלעומת הבטן ( פסוק כ ), מלקבל דבקא. וגובה שתי האגנות האלה ארבע אמות, וזהו שאמר ( פסוק יט ): **ומעשה שושן באולם ארבע אמות.** מצוירות היו בם כמין פרחי שושנים, כדרך הציורין בכותל האולמות, ארבע אמות גובה, והאמה החמישית, היא כותרת קטנה למעלה מן הגדולה, הוא שנאמר ( פסוק כ ): וכותרת על שני העמודים:
@141 **גם ממעל מלעומת הבטן.** שהוא לעבר השבכה, בסוף השבכה בשוליה, הוא באמצע במקום הדבק ( שעל השבכה ) ( צריך לומר: שהשבכה ) מדובקת בגולה אשר תחתיה: **והרמונים מאתים.** רמונים עשוין שתי טורים סביב, מחורזים בשלשלת, ומקיפין את השבכה: **על הכותרת השנית.** אף זה מקרא קצר, על האחת, וכן על השניה:
@143 **ועל ראש העמודים מעשה שושן.** חצי אמה בראש כל אחד היה כותלו דק כשושן, ושאר העמוד עוביו ארבע אצבעות נבוב, לכך לא נמנית אותה אמה ביציקת העמודים בדברי הימים, לפי שלא היתה שוה למלאכת העמוד:
@144 **עשר באמה משפתו עד שפתו.** באמצעיתו, שכל רוחב כלי עגול, באמצעיתו הוא: **קומתו.** עומקו, ובדברי הימים ( ב ד ו ) הוא אומר, שעשאו לרחיצת הכהנים לטבול בתוכו: **וקו שלשים באמה.** זהו שאמרו כל שיש בהקיפו שלשה טפחים יש בו רוחב טפח, הקיפו שלשים, ורחבו עשר, ומתוכו הוא מודד, ( בערובין יד א ):
@145 **ופקעים.** וצורת ביעין, תרגם יונתן: **מתחת לשפתו.** בשלש אמות תחתונות שהיו מרובעות, שכך שנינו בגמרא דעירובין ( שם עמוד ב ): שלש תחתונות מרובעות, ושתים עליונות עגולות, ואי אפשר לו להכיל אלפים בת, שהם מאה וחמשים מקוה טהרה ארבעים, אלא בענין זה כמו שפירשו רבותינו בעירובין, עליונות מרובעות והתחתונות עגולות, אי אפשר לומר, דכי כתיב שפתו עגול סביב, לכך הוא אומר: בפקעים הללו עשר באמה מקיפין את הים סביב, שבמקום ריבועו ( הקיפו ) ארבעים אמה, עשר אמה לכל רוח, אבל במקום עיגולו אי אפשר לומר עשר באמה סביב: **שני טורים הפקעים יצוקים ביצקתו.** הכל מוצק יחד, לא שחבר לו את הפקעים אחר יציקתן על ידי מסמרות או על ידי דבק, שקורין שולדר"א בלע"ז:
@146 **וכל אחוריהם.** של בקרים הללו: **ביתה.** אל תחת הים היו אחוריהם פונים [ שלשה ] ( שנים ) שבצפון לקראת שבדרום, ושל מזרח כנגד של מערב:
@147 **ועביו טפח.** שוליו ודופנותיו, אלא שאצל פיו היה דק ומרוקע ומרודד, כמעשה שפת כוס ששותין בו, ומצוייר פרח ושושן: **אלפים בת.** ששת אלפים סאים, שהבת שלש סאין, שנאמר ( יחזקאל מה יא ): **האיפה והבת תוכן אחד להם.** נמצאו חמשים ומאה מקוה טהרה, הארבעים מאות, מאה מקואות, והעשרים מאות, חמשים מקואות ( עירובין שם ). ואף כשתחלוק הכל לפי מדה ששיערו חכמים אמה על אמה ברום שלש אמות למקוה, תמצאנה כן, שלש אמות מרובעות, מאה מקואות, ושתים העגולות, חמשים מקואות, שהמרובע יתר על העיגול רביעית. ובדברי הימים ( ב ד ה ) כתיב: בתים שלשת אלפים יכיל, ופירשו רבותינו ( שם ) במדת היבש, שהגודש היה שליש בבית הקיבול:

@1 **הנה אלו** הדברים בכללם כבר קדם זכרם במה שעבר ומשם ילקח פירושם זולתי דברי' מועטי' נתחדשו בהם והם אשר נשתדל לבארם עתה הנה הקדים משה בזה הספור זכרון שמירת השבת לעשיית המשכן וכל אשר בו אע"פ שהיה מאוחר במה שקדם מדברי השם יתע' אלא לפי שהכונה בזה הוא להודיע שאין מלאכת המשכן דוחה שבת והקדימו משה מפני זה והנה נתחדש בה אזהרה אחת והיא אמרו לא תבערו אש בכל מושבותיכם ביום השבת ואמר בכל מושבותיכם כי במקדש יבערו אש המזבח ביום השבת ולפי שאמר בכל מושבותיכם והיו קצת המושבות לדיינין הדנין דיני נפשות למדנו מזה שאין דיני נפשות דוחין את השבת אף על פי שהם מצוה כי הבערה היא אחת ממיתות ב"ד המו שיתבאר במה שיבא והנה נמנעה בשבת והוא הדין לשאר מצות ב"ד. וידמה שלזה הענין לבד הוצרכה זאת האזהרה כי כבר קדמה האזהרה מעשות מלאכה בזבת והנה ההבערה היא אחת מהמלאכו' ואמנם מפני שהעירנו על שאין מלאכת המשכן דוחה שבת ואם היא מצוה העירנו ג"כ על שאין מיתת ב"ד דוחה שבת ואם היא מצוה והסבה בזה כלו מפני שלא נקבע מועד מוגבל לאלו הדברים ולזה אינם דוחים את השבת והנה יתבאר מזה המקום גם כן שכבר יתחייבו בשבת על אחת אחת מהמלאכות שכבר היה בא לאו ביחוד על ההבערה שהיא אחת מהמלאכות שכבר היה בא לאו ביחוד על ההבערה שהיא אחת מהמלאכות וכן הענין בשאר המלאכות ולזה אמרו ז"ל כי ההבערה לחלק יצאת וענין זה החלוק הוא שאם עשה האדם מלאכות הרבה בהעלם אחד חייב חטאת על כל אחת ואחת ואף על פי שנכללו כל המלאכות בלאו אחד שכיון שבא לאו ביחוד כאחד מהם למדנו שהלאו שם אל אחת אחת מהמלאכות ולזה תהיה כל אחת מהם ממצות יי' אשר לא תעשינה שיתחייב עליהם חטאת כשנעשו בשגגה כמו שנתבאר בפרשת ויקרא ואת פרכת המסך אין הרצון שתהיה מסוככת אבל הרצון בזה הענין גדר ומחיצה כטעם הנני סך את דרכך בסירים:
@22 **ויבאו האנשים על הנשים.** ר"ל אצל הנשים והרצון בזדה שכבר נתעוררו יחד להביא הצריך לזאת המלאכה לפי נדבתן והנמצא אתם מאלו הדברים:
@26 **וכל הנשים אשר נשא לבן אותנה בחכמה טוו את העזים.** ידמה שיהיה בטויית העזים מהאומנות והחכמה יותר משיהיה בזה בטויית הצמר:
@41 **איש ואשה על יעשו עוד מלאכה.** מלאכת הקדש:
@41 **ויכלא העם מהביא.** למדנו מזה המקום שההבאה תקרא מלאכה ולזה יתחייבו עליה בשבת ומזה המקום נלמד שאין ראוי לאדם שיקדיש לשם יתעלה מנכסיו יותר מן הראוי וכן ההקש בענין הצדקה ולזה אמרו המבזבז אל יבזבז יותר מחומש כדי שלא ישוב להיות עני ויצטרך לבריות וזה שהוא ראוי שנזהר בפעולות הטובות שלא יעשו באופן שיקרה מהם רע פן ירחקו האנשים מהן וזה שאם בא האדם לעני בסבת רוב הצדקות וההקדשות יאמרו האנשים ראו מה התועלת בהקדשות ובצדקות הלא פלוני היה משתדל בענינם בתכלית מה שאפר והעני יביא זה אל שירחקו האנשים מעשיית אלו הפעולות הטובות:
@41 והנה סדור המלאכה לא היה באופן שזכרו משה במה שקדם כי הסדור ההוא הוא הנאות לפי הענין וזה הסדור הנזכר הוא הנאות לפי עשיית המלאכה ולא זכר תחלה עשיית משכן והפרוכת ואח"כ עשיית הארון והכפורת כי היה ראוי שתהיה מלאכ' המשכן והפרוכת ואח"כ עשיית הארון והכפרות כי היה ראוי שתהיה מלאכ' המשכן קודמת למלאכת הארון אשר יושם בו והנ' זכר עשיית היריעות קודם לעשיית הקרשי' כי אין ראוי שיעמידו הקרשים אם לא היו תחלה היריעות מוכנות לכסות אותם ולהיות לאהל על המשכן כדי שלא תראה זאת המלאכה חסרה זה הזמן הארוך אשר יעשו בו היריעו':
@110 **ויעש את הכיור נחשת וכנו נחשת במראות הצובאות אשר צבאו פתח אהל מועד.** הנה אלו המראות היו מנחשת מזוקק כדי שישלם בו רושם התמונה וכבר נתקבצו צבא מהם להתנדב אלו המראות לפי שלא היה להם נחשת אחד להשלים המלאכה וזה מורה על הפלגת נדבת לבם להביא המצטרך לזאת המלאכה ואולם אמר במראות הצובאו' כי תמונת הכיור וכנו עשה בנחשת ההוא על צד מה שיאמר שהצור' הוא בחמר וזה הוא אחד מהדרכים שיאמר בהם שהדבר בדבר כמו שזכר הפילוסוף בספר השמע או תהיה הבי"ת תמורת מ"ם והרצון בו שהוא עשה הכיור וכנו ממראות הצובאות וכבר מנו מזה המין בעלי הלשון הרבה:

@1 **ביאור דברי הפרשה:**
@1 וראוי שנעיין בהתרת ספק עמוק יקרה בזה הספור וברבים מספורי התורה וזה שהוא ראוי בתורה מצד שלמותה שלא יהיה בדבריה כפל ומותר. ואנחנו רואים בזה המקום הכפל בלתי צריך אליו יהיה די בשיאמר ויעש בצלאל בן אורי בן חור את כל מלאכת המשכן כאשר צוה יי' את משה ואתו אהליאב בן אחיסמך וגו'מ. וכבר מצאנו כמו זה ההכפל במקומות רבים מן התורה ולא מצאנו עד היום בזה סבה כוללת מספקת ואפשר שנאמ' שכבר היה מנהג האנשים ההם בזמן מתן תורה שיהיו ספוריהם בזה האופן והנביא אמנם ידבר לפי מנהג או נאמר כי מפני שקצרה התורה במקומות רבים העמוקים האריכה זה האריכות במקומות האחרים אשר האריכו' ההם בלתי מזיק כדי שלא נחשוב כי הקצור היה במקומות ההם לפי שמנהג התורה לדבר בקצור כי כבר נראה מנהגה לדבר באריכות ולזה נתעורר לבקש הסבה מפני מה קצרה התורה במקומות העמוקים ההם ונעמוד מפני זה על טבע הנושא אשר בו הדברי' ההם כי הוא הסבה בקצור ההוא ונעמוד מפני זה על כונת התורה באותם הדברים הקצרים כשנעיין בהם בכל הצדדים שאפשר לעמוד מהם על כונתיהם ואפשר שנתן בזה המקום סבה מיוחדת וזה כי למדנו בזה ההכפל שכל הדברים שנזכרו בזאת המלאכה הם מכוונים ולזה לא השמיט אחת מהם עושי המלאכה. וזה ממה שיעמידנו על בקשת הסבות למה היו אלו הדברים בזה האופן ונעמוד מפני זה על כונת התורה בזאת המלאכה ועוד כי מפני של היה הסדור במלאכ' הסדור אשר היה בדברי השם עם משה למדנו כי הסדור ההוא שבא בדברי הש' ית' למשה הוא לפי טבע הענין בעצמו אשר העירה עליו המלאכה ההיא והסדור ההוא שבא בעשיית המלאכה הוא לפי טבע המלאכה כי יחוייב שתקדם עשיית האהל לעשיית הכלים שישימו בו וזה ממה שיישר אותנו על העמיד על כונת התור' בזאת המלאכה הנפלאה ובכאן נשלם הביאור בזה הספר:
@1 והיתה השלמתו בראש חדש אלול של שנת תשעים לפרט האלף הששי ליצירה יתברך ויתעלה האל אשר עזרנו כרב רחמיו וחסדיו על כל ברכה ותהלה אמן אמן סלה:
@1 ואולם אלו השני שרשים אין כאן שרשם והם שייכים בפרשת משפטים דף פ"ח עמוד שלישי. ואולם השמטנו אותם בלא כוונה. וידוע כי אונס פטור רחמנא:
@1 **השרש** הנ"א הוא שהשור שנגח שור רעהו פטור כגון שהיה השור הניזק של הקדש וכן אם היה השור המזיק של הקדש והניזק של הדיוט שאין אני קורא שור רעהו אך אם היה בו חלק לרעהו וחלק להקדש הנה יהיה חלק ההדיוט כנגד החיוב אם הזיק או הוזק כבר נתבאר זה השרש בראשון וברביעי מבבא קמא:
@1 **השרש** הנ"ב הוא שאין הבדל בנזק השור בין שהזיק ב"ח או שבר את הכלים ובין שהמית הב"ח או שחב בו כשיהיה זה באופן שיהיה בו פשיעה לבעל השור ר"ל כשהיו הכלים במקום שדרך האנשים להניח שם כליהם וזה מבואר מאד כי כוונת התורה בזה היא לסלק ההזיקי' כלם מבין האנשים והנה ישלם נזק הכלי כשישומו מה שהיה שוה קודם שבירתו וכמה הוא שוה אחר שבירתו כמו הענין בהמתתו הב"ח שישומו מה שפחתתו זא המיתה מדמיו כבר נתבאר זה השרש בראשון ובחמישי מבבא בתרא ומזה יתבאר שאם חבל הב"ח וכחש אחר זה מחמת מכה משלם לו המזיק מן הכחש ההוא לפי משפטו ר"ל שאם היה תם משלם חצי נזק מגופו ואם היה מועד משלם נזק שלא וזה החש היתה סבתו המכה בעצמות ואי אפשר לאומר שיאמר שכבר היה אפשר לו לשוחטה או למכרה תכף קודם שתתכחש יותר כי לא היה אפשר זה לו קודם שיראה לדיינין זה הנזק וישפטו ביניהם ואולם במיתה הוא פחת הנבלה על הניזק שכבר היה בידו למכר' תכף קודם שתתעפש כי אין צריך שיראה הנבלה לדיינים אחר שכבר נתבאר זה המתת הב"ח בסבת נגיחת השור ההוא כי שעור ההמתה לא יתחלף בפחו' וביתר כמו הענין בחבל ולזה לא יתחייב בפחת הנבלה מזאת ההמתה בעצמות וכן מה שיתחייב במקרה מההפסד בעבור המכה לא יתחייב בו המזיק והמשל שהשמין ופטם הניזק השור הנחבל ויודע שלולא המכה ההיא היה משביח מזה יותר שעור רב אם פטמוהו בזה האופן לא יתחייב המזיק כי אם מה שפחתתו המכה בזולת פטומו הבהמה ולפי שזה אי אפשר שיודע הנה ישלם מה שפחתתו המכה בעת החבל כבר נתבאר זה השרש ברביעי מבבא קמא. ע"כ:

@123 **ויעש חירם את הכיורות.** הרצון בו הסירות וכן אמר אחר זה ואת הסירות ואת היעים וכן כתוב בדברי הימים בשני אלו המקומות והנה ענין אלו הכיורות הוא מענין אמרו והכה בכיור או בדוד והנה אלו הסירות היו משמשות לשום בהם דשן המזבח:
@128 **ואת היעים.** הם מגרפו' של נחושת לדשן בהם המזבח: **ואת המזרקות.** הם כלים יקבלו בהם הדם להזות על המזבח: **ואת כל הכלים האלה.** קרי וכתיב הכלים האהל והנה תרגם יונתן לפי הכתב שאלו הכלים היו נעשים כצורה שעשאם משה באהל ומזה אמרו ואת כל הכלים האהל כאילו אמר את כל הכלים כלי האהל וכמוהו רכים בלשוננו: **נחשת ממורט.** ר"ל צרוף ונקי מכל סיג:
@129 **בככר הירדן.** ר"ל במישור הירדן: **במעבה האדמה.** ר"ל שחפר בעובי האדמה צורת הדפוסים להתיך את כל הכלים האלה כי לא היה נכון לגדלם לעשות להם דפוסים יותכו בהם זולת זה הדרך:
@130 **וינח שלמה את כל הכלים.** ר"ל כי מרוב משקלם הניח שלמה מלחקור על משקלם כמה היה:
@131 **ויעש שלמה את כל הכלים אשר בית ה'.** ר"ל אשר בבית ה': **את מזבח הזהב.** הוא מזבח הקטרת אשר היה בהיכל: **ואת השולחן אשר עליו לחם הפנים זהב.** כבר נתבאר בספר דברי הימים כי שלמה עשה עשר שולחנות והניחם בהיכל חמשה מימין וחמשה משמאל שיהיו קצת השולחנות לפאת צפון וקצתם לפאת דרום כי כבר התבאר מדברי התורה שמקום השולחן היה בצפון והמנורה היתה בדרום אבל הרצון בזה שלפאת צפון שם השלחנות בשתי שורות האחת לפאת ימין מהאחרת וכן ראוי שנבין מענין המכונות והנה לא זכר מעשה השולחן והמנורות לפי שכבר עשאם באופן שנזכר בתורה:
@132 **לפני הדביר זהב סגור.** הנה מפני שהשולחנות הם גם כן לפני הדביר ולא זכר זה אלא במנורות ידענו שהמנורות יותר קרובות מקדש הקדשים מהשולחנות והם היו כנגד הארון כי לפני ה' היו כמו שהתבאר מדברי התורה ומה שאמר והפרח והנרות והמלקחים זהב אין הרצון בו שלא יהיה השאר גם כן זהב אבל הרצון בו שעד פרחה שהיה בסוף ירכה ועד הנרות שהיו בקצה המנורה השני הכל הי' זהב וכן המלקחים היו זהב כמו שהוגבל בתורה וככה אמר בתורה עד ירכה עד פרחה זהב טהור: **זהב סגור.** ר"ל נקי ומזוקק וידמה שזקוקו היה בשיסגרוהו תוך הכור באש עם דברים יוציאו ממנו סיגיו בעשן ולזה נקרא סגור:
@133 **והספות.** הם בדמיון כדים העשויים לשום בהם יין: **והמזמרות.** הם כלי זמר עשוים מזהב, ואפשר שיהיו גם כן הספות מינים אחרים מכלי זמר: **והמזרקות.** הם לקבל הדם ואחשוב שהיו משמשים לדם קדשים אשר יובא אל הקדש פנימה: **והכפות.** הם לשום בהם מלא קומץ לבונה להקטיר: **והמחתות.** הם לחתות בהם גחלים להוליך ממזבח החיצון למזבח הזהב: **והפותות לדלתות הבית.** ר"ל מה שיכנס ציר הדלת בו שהוא מחובר לדלת, הנה זה היה בדביר ובהיכל מזהב:
@134 **וישלח המלך שלמה ויקח את חירם וגו'.** זכר שאביו גם כן היה חרש נחשת ולזה היה הבקיאות לו יותר בזאת המלאכה:
@136 **ויצר את שני העמודים.** ר"ל שהוא עושה צורתם מפני עשותו הדפוס שבו השליך הנחשת אחר שהתיכו: **שמנה עשרה אמה קומת העמוד האחד.** בספר דברי הימים התבאר שקומת שניהם היתה שלשים וחמש אמות ויחסר מזה אם כן אמה, ואפשר שנאמר שלא דקדק בזה כמו שלא דקדק בכמו האופן הזה במקומות רבים שאמר על דוד בחברון מלך שבע שנים וששה חדשים ובירושלם מלך שלשים ושלש שנה ובמקום אחר אמר כי הימים אשר מלך דוד הם ארבעים שנה: **וחוט שתים עשרה אמה יסוב את העמוד השני.** מזה התבאר כי קוטר עגול העמוד היה כמו שלש אמות וארבע חמישיות אמה בקירוב והנה התבאר בספר ירמיה כי העמוד היה חלול והיה עביו ארבע אצבעות:
@137 **ושתי כותרות עשה לתת על ראשי העמודים מוצק נחושת.** ר"ל שהתוך נחשת ועשה לתת על ראש העמודים מוצק נחשת כצורת שני כתרים דבוקי' זה בזה כל אחד מהם כצורת אבן ומצד אחד היה נכנס בהם העמוד, והנה אמר בזה המקום שקומת הכותרת היתה חמש אמות ובסוף זה הספור אמר שקומתם היתה ג' אמות וזה ראיה שהשתי אמות התחתונות היתה כמו מלאכת העמוד והיה העמוד הנכנס בהם ומזה יתבאר שרוחב הכותרות גדול מעמקם כי זה רחבם היה מוסיף על רחב העמוד ורחב העמוד הוא שלש אמות וארבעה חומשי אמה בקירוב כמו שקדם:
@138 **שבכים מעשה שבכה.** הוא מעשה רשת קרשפינ"ה בלע"ז והיתה מקפת כל הכותרת ממעל ומתחת: **גדילים מעשה שרשרות לכותרות.** הם טרינא"ש בלע"ז והיו מוקפים מהם שבעה על כל שבכה:
@139 **ויעש את העמודים ושני טורים סביב על השבכה האחת.** אחשוב שהעמודים האלו היו טורים עומדים בגובה בשבכה ואילו העמודים היו קבועי' בשבכה בשני גדילים ממנה ביותר רחב וכאשר נמשך אחריו מהשבעה גדילים אשר בכל שבכה והיה זה לכסות את הכותרת אשר על ראש העמודים והיא האבן העליונה והנה תהיה אות וי"ו במלת ושני טורים כפ"א רפה בלשון ישמעאל והרצון בו ויעש את העמודים שני טורים וירצה בזה שכבר עשה את העמודים בשבכה באופן שתארנו ועשה אותם שני טורים והכונה אחת ממה שזכרנו קודם:
@140 **וכותרות אשר על ראש העמודים.** ר"ל שכבר עשה זה בכותרות אשר על ראש העמודים והם האגנות העליונות ציור שושנים ופרחים היו עולים על ראש הכותרות באולם ארבע אמות ואחשוב שזה הציור היה נעשה בשני טורי העמודים היוצאים מן השבכה כי העמודים ההם היו גבוהים על ראש הכותרות והיה בהם צורת פרחים ושושנים:
@141 **וכותרות על שני העמודים וגו'.** הם הכותרות התחתונות ר"ל האגנים התחתונים המביטים אל העמודים הגדולים וירצה בזה שבמה שהיה מהם מביט לעמודים היה טור רמונים וגם ממעל למקום ההוא מלעמת הבטן והוא אמצע דבוק שתי האגנות כי המקום ההוא בלתי רואה העמודים היה טור רמונים, והנה היה בכל טור מהם מאה רמונים כמו שכתוב בספר דברי הימים באמרו ואת הרמונים ארבע מאות לשתי השבכות שני טורים רמונים לשבכה האחת לכסות את שתי גלות הכותרות אשר על פני העמודים, והנה הרמונים תלוים בשרשרות כמו שנזכר שם וידמה שהשרשרות שהיו שבעה לכל כותרת היו שלשה בגלה העליונה ושלשה בגלה התחתונה והאחת במקום דבוקם והיא היתה לעומת הבטן, הנה אמרו בזה המקום כי הרמונים היו מאתים טורים סביב אין הרצון בו שיהיו מאתים טורים כי זה אינו כמו שזכרנו אך הרצון בזה שהרמונים היו מאתים טורים סביב ר"ל שהיו מסודרים בשני טורים סביב:
@142 **ויקם את העמודים לאולם ההיכל.** ר"ל שהקימ' בו ולא היו נעשים, והנה קרא שם העמוד הימיני והוא אשר לפאת דרום יכין ושם העמוד אשר לפאת צפון קרא בועז כאילו העיר בזה על סוד גדול מהכוון מענין כלי בית המקדש כמו שבארנו מענינם בספר ואלה שמות והוא ידוע כי הש"י שם בטבע בתקופות הארבע רושם להויות השפלות והתקופות השתים השמש בהם דרומי הם מכינות ההויות ובתקופות הנשארות יהיה הטבע חזק ועז לעשות פעולותיו וזה מבואר נגלה בצמחים כי הם יקחו רושם מאלו התקופות יותר ממה שיקחו מהם הב"ח ולזה סמך אל זה הענין משמות העמודים של ראש העמודים מעשה שושן והנה נבאר זה באור יותר בג"ה בזכרנו התועלות המגיעים מזה:
@144 **ויעש את הים מוצק וגו'.** הנה התבאר בספר דברי הימים כי הים היה משמש לרחצה לכהנים בו וכדי שלא יהיו המים שאובין צריכים אנו לומר שרגלי הבקרים היו מלמטה והיו המים באים שם מלמטה נובעים מהקרקע ונכנסים שם, והנה זכר שהיה רחב הים משפתו אל שפתו עשר אמות והיה עגול סביב והיה חמש אמות קומתו, והנה אמרו שקו שלשים באמה יסוב אותו סביב הוא על דרך קירוב כי ההיקף בעגול הוא מוסיף על שלשה בשעור בקוטר כמו שביעית הקוטר בקירוב מעט ואם אמרנו שמדת הקו הסובב היא לקוחה בחלל הים הנה יהיה יותר קרוב אל האמת אך יהיה בו קירוב מעט כי עביו היה טפח ולזה יהיה קטר חללו עשר אמות פחות שלישית אמה ויהיה הקיפו בקירוב יותר על שלשים אמה אמה ושלישית אמה:
@145 **ופקעים מתחת לשפתו סביב.** הם כמו צורת ביצים כמו שזכרנו במה שקדם והיו מהם עשר באמה בדרך שיהיו מהם בכל ההקיף שלש מאות ולזה היו מהם בשני הטורים שש מאות והם היו יצוקים ביציקת הים לא שיהיו שם מסובכים אחר כן אך בהתכה הים נעשו עמה אלו הפקעים יחד ולפי שבספר דברי הימים כתוב תמורת הפקעים בקרי' הנה ידמה שהיה בכל פקע צורת ראש שוד יצאו המים מפיו והנה אמרו רבותי' ז"ל שלא היה הים עגול אלא בשפתו אך מתחת היה מרובע וזה נתבאר להם מהשעור שהיה מחזיק שהוא אלפים בת והבת היא שלש סאין כאמרו האיפה והבת תוכן אחד להם ולפי שאמה על אמה ברום שלש @ אמות היא מחזקת ארבעים סאה כמו ששערו חכמים הנה תהיינה אלפים בת שהם ששת אלפים סאים ארבע מאות וחמשים פעם אמה על אמה ברום אמה והנה האמה גובה מזה היה העגול אמה מהאמות הנזכרים כי הם כמו שבעים וארבע אמות בקירוב ולא יהיו בחמש אמות שבגובה הים כי אם שלש מאות ושבעים אמה בקירוב וזה פחות ממה שזכרנו שמונים אמה ולזה יחוייב שתהיינה קצת האמות מרובעות וכן מצאנו במכונה שהיתה מרובעת והיה בראש המכונה חצי האמה קומה עגול סביב ואמרו ז"ל ששלש אמות התחתונות היה בהם הים מרובע ובשתי אמות העליונות היה עגול ובזה יתאמת מה שזכרנו בקירוב ובזה יאות יותר מה שזכר מצורות הבקר שהיה הים מונח עליהם שהיו מהם שלשה לכל רוח:
@146 **והנה** היו פני הבקר בחוץ נראים ואחוריהם היו נסתרים תחת הים:
@147 ועביו טפח ושפתו כמעשה שפת כוס פרח שושן. שמצוייר בו פרח, והנה אמר בזה המקום אלפים בת יכיל ובספר דברי הימים אמר מחזיק בתים שלשת אלפים יכיל ואמרו רז"ל שאשר נזכר בזה המקום הוא בלח אך ביבש יחזיר יותר מפני הגודש ויהיה אם כן גודש הים מחזיק כמו חצי השיעו' שמחזיק הים וזה אפשד כשהיה הדבר הנגדש עולה על הים שיעור רב:
